#include "opensim/scene/task_inventory_update.hpp"
#include <iostream>
#include <bit>
using namespace opensim;using namespace scene;
namespace {
framework::Uuid id(int n){auto s=std::to_string(n);return framework::Uuid("11223344-5566-7788-99aa-"+std::string(12-s.size(),'0')+s);}
using Item=TaskInventoryUpdateBackend::Item;
std::string dump(Item i){if(!i)return "NULL";return std::to_string(i->base_permissions)+","+std::to_string(i->current_permissions)+","+std::to_string(i->everyone_permissions)+","+std::to_string(i->group_permissions)+","+std::to_string(i->next_permissions)+","+std::to_string(i->flags)+","+i->asset_id.str()+","+i->owner_id.str()+","+i->group_id.str();}
std::string probe(int mode,int mask,int failure){auto bit=[&](int b){return (mode&b)!=0;};std::string trace;auto step=[&](int p,std::string s){trace+='|'+s;if(p==failure)throw std::runtime_error("injected");};std::uint32_t masks[]={0,0xffffffffu,0x9e000,1,0x12345678,0x80000,0x7fffffff,0x80000000};auto base=masks[mask&7];auto current=std::make_shared<framework::TaskInventoryItem>();current->item_id=id(2);current->base_permissions=base;current->current_permissions=base^0x2000;current->everyone_permissions=base^0x4000;current->group_permissions=base^0x8000;current->next_permissions=base^0x10000;current->flags=0x12345678;current->asset_id=id(4);current->owner_id=id(1);
 auto input=std::make_shared<framework::TaskInventoryItem>();input->item_id=bit(1)?framework::Uuid{}:id(2);input->base_permissions=base^0x40000;input->current_permissions=base^0x10000;input->everyone_permissions=base^0x20000;input->group_permissions=base^0x80000;input->next_permissions=base^0x100000;input->flags=0xffffffff;input->asset_id=id(5);input->owner_id=bit(16384)?framework::Uuid{}:id(1);input->group_id=bit(32768)?id(6):framework::Uuid{};if(bit(8388608))input=current;if(bit(16777216))input.reset();
 TaskInventoryUpdateBackend b;TaskInventoryUpdatePart part{id(3),bit(8192)?id(9):id(1),123};b.part=[&](auto local)->std::optional<TaskInventoryUpdatePart>{step(3,"PART:"+std::to_string(local));if(bit(2))return {};return part;};b.task_item=[&](const auto&,auto){step(4,"GETTASK");return bit(4)?Item{}:current;};
 auto user=[&]{services::InventoryItem item;item.id=id(2);item.name="Drop";item.current_permissions=bit(1024)?0:0x8000;return item;};b.inventory_item=[&](auto,auto)->std::optional<services::InventoryItem>{step(5,"USER");if(bit(8))return {};return user();};if(!bit(16)&&!bit(32))b.library_item=[&](auto)->std::optional<services::InventoryItem>{step(6,"LIBRARY");if(bit(64))return {};return user();};
 b.can_drop=[&](const auto&,const auto&,const auto&){step(7,"DROP");return !bit(128);};b.can_edit_object=[&](const auto&,const auto&){step(8,"EDITOBJECT");return !bit(256);};b.random_uuid=[]{return id(5);};b.add_group=[&](auto,const auto&,auto,const auto& item,auto copy,bool modify){step(9,"ADD:"+std::string(copy.is_zero()?"0":"1")+":"+(modify?"1":"0"));if(bit(33554432))const_cast<services::InventoryItem&>(item).current_permissions=0;};if(bit(2097152))b.fetch_remote_assets=[&](auto,const auto&){step(11,"REMOTE");};b.properties=[&](const auto&,const auto&){step(12,"PROPERTIES");};b.bypass_permissions=[&]{step(13,"BYPASS");return bit(512);};b.remove_user_items=[&](const auto&,const auto& keys){step(14,"REMOVE:"+keys[0].str());};b.can_edit_inventory=[&](auto,auto){step(15,"EDITINV");return !bit(2048);};if(bit(1048576))b.transaction_update=[&](const auto&,const auto&,auto,auto item){step(16,"TRANSACTION");if(bit(4194304)){item->base_permissions=0x1234;item->flags=0x555;}};b.is_god=[&](auto){step(17,"GOD");return bit(4096);};b.update_item=[&](const auto&,auto i){step(20,"UPDATE:"+dump(i));return !bit(262144);};b.error=[&](auto){step(1,"ERROR");};b.warn=[&](auto){step(2,"WARN");};b.info=[&](auto){step(10,"INFO");};TaskInventoryUpdateClient client{id(1),[&](auto){step(18,"MEMBER");return bit(65536);},[&](auto)->std::uint64_t{step(19,"POWERS");return bit(131072)?0x4000000000ull:0;}};std::string result="OK";try{TaskInventoryUpdateController(std::move(b)).update(client,bit(524288)?id(7):framework::Uuid{},input,123);}catch(...){result="THROW";}return result+":"+dump(current)+":"+dump(input)+trace;
}
}
int main(int argc,char** argv){try{if(argc>1&&std::string_view(argv[1])=="--probe"){int mode,mask,failure;while(std::cin>>mode>>mask>>failure)std::cout<<probe(mode,mask,failure)<<'\n';return 0;}int checks=0;auto check=[&](bool ok,const char* s){++checks;if(!ok)throw std::runtime_error(s);};check(probe(0,0,0).find("|UPDATE:")!=std::string::npos,"owner updates");check(probe(1,0,0).find("|PART:")==std::string::npos,"zero item before lookup");check(probe(4|1024,0,0).find("|REMOVE:")!=std::string::npos,"drop consumes noncopy");check(probe(4|1024|512,0,0).find("|REMOVE:")==std::string::npos,"bypass retains noncopy");check(probe(524288|1048576|2048,0,0).find("|TRANSACTION")==std::string::npos,"permission before transaction");check(probe(0,0,20).find("|PROPERTIES")==std::string::npos,"failed update before properties");auto packet=network::lludp::make_packet("UpdateTaskInventory");packet.block("UpdateData")["Key"]=std::uint64_t(1);check(!task_inventory_update_request(packet),"asset key ignored");packet.block("UpdateData")["Key"]=std::uint64_t(0);packet.block("InventoryData")["Name"]=std::vector<std::uint8_t>{'A','B'};packet.block("InventoryData")["CreationDate"]=std::int64_t(-1);auto decoded=task_inventory_update_request(packet);check(decoded&&decoded->item->name=="A"&&decoded->item->creation_date==0xffffffffu&&decoded->item->asset_id.is_zero(),"source wire projection");std::cout<<"PASS: "<<checks<<" task inventory update checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
